import{_ as i,l as r,o as e,c as d,v as t,p as n,x as o,d as c,i as p,S as s}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"上下文感知解码","description":"","frontmatter":{"title":"上下文感知解码","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/context-aware-decoding.md","filePath":"llm/context-aware-decoding.md","lastUpdated":1789023840000}'),A={name:"llm/context-aware-decoding.md"};function h(m,a,E,_,D,g){const l=r("Mermaid");return e(),d("div",null,[a[1]||(a[1]=t('<h1 id="上下文感知解码" tabindex="-1">上下文感知解码 <a class="header-anchor" href="#上下文感知解码" aria-label="Permalink to &quot;上下文感知解码&quot;">​</a></h1><div class="epigraph"><p>模型有时更相信自己的参数记忆，而不是你刚贴上的证据；把「有上下文」与「无上下文」的分布对比，才能把生成拉回当前证据。</p><footer>—— Shi et al., Trusting Your Evidence: Hallucinate Less with Context-aware Decoding, NAACL 2024</footer></div><p><a href="/llm/dola-decoding">上一课</a>对比的是同一前向里的深浅层，对象是参数里的「先验 vs 事实」。本课把对比轴换成 <em>条件</em>：同一层、同一权重，一次看见检索到的证据 \\(c\\)，一次看不见。Shi 等人的 Context-aware Decoding（CAD）用有上下文的 logits 减去无上下文的 logits，放大那些「只因为看见 \\(c\\) 才升高」的 token。它针对的是上下文接地（context-grounded）生成：摘要、RAG、阅读理解。不要把 CAD 写成通用抗幻觉开关——没有 \\(c\\)，对比无定义。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>RAG 与长提示把证据写进前缀，但逐步分布仍可能跟参数里更强的共现走：实体名触发了训练中的高频属性，证据里的相反属性被忽略。这是忠实性问题在解码端的版本：<a href="/llm/dola-decoding">上一课</a>假设事实在深层；这里事实在 <em>提示</em> 里，模型却不「信」。缺口是：如何在不改权重、不重训的前提下，提高 \\(c\\) 对下一步的因果作用。</p><p>朴素做法「把证据重复三遍」浪费上下文窗口，且不保证逐步对齐。CAD 的对比明确针对这一点：无上下文分布 \\(p_\\theta(\\cdot\\mid x)\\) 代表先验，有上下文 \\(p_\\theta(\\cdot\\mid c,x)\\) 代表先验加证据；差放大后者相对前者多出来的质量。</p><p><span class="marginnote">两次前向共享大部分计算图，但不共享 KV：无上下文那次没有 \\(c\\) 的键值。实现上这是两次 decode 步，或一次 batch=2 的前向。比 DoLa 的中间层钩子更贵，比 MBR 仍便宜。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>令 \\(z^+\\) 为条件于 \\((c,x,\\text{prefix})\\) 的 logits，\\(z^-\\) 为只条件于 \\((x,\\text{prefix})\\) 的 logits（生成前缀仍要一致，否则对比的不是「证据」，而是另一条链）。对比</p> \\[p_{\\mathrm{CAD}}(x_t)\\propto \\mathrm{softmax}\\big(z^+ + \\alpha(z^+-z^-)\\big), \\]<p>\\(\\alpha\\gt 0\\) 是放大系数（原文把对比写成对点分的加权）。\\(\\alpha=0\\) 退回普通有上下文解码；\\(\\alpha\\) 过大把只在 \\(c\\) 里出现的罕见拼写放大成胡话。温度与 top-p 加在对比之后，顺序同<a href="/llm/sampling-temperature-topp">核采样</a>。</p><p>无上下文那条链的 KV 可以更短（没有 \\(c\\)），但生成前缀必须同步追加，否则 \\(z^-\\) 条件错位。投机解码时，草稿若只跑 \\(z^+\\)，目标用 CAD，接受规则对的不是 CAD 分布——要么两边都做对比，要么承认有损加速。</p>',12)),(e(),n(s,null,{default:o(()=>[p(l,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20C%5B%22%E8%AF%81%E6%8D%AE%20c%20%2B%20%E6%8F%90%E7%A4%BA%22%5D%20--%3E%20ZP%5B%22%E6%9C%89%E4%B8%8A%E4%B8%8B%E6%96%87%20logits%22%5D%0A%20%20X%5B%22%E6%97%A0%E8%AF%81%E6%8D%AE%E6%8F%90%E7%A4%BA%22%5D%20--%3E%20ZM%5B%22%E6%97%A0%E4%B8%8A%E4%B8%8B%E6%96%87%20logits%22%5D%0A%20%20ZP%20--%3E%20CAD%5B%22%E6%94%BE%E5%A4%A7%20z%2B%20%E7%9B%B8%E5%AF%B9%20z-%20%E7%9A%84%E5%B7%AE%22%5D%0A%20%20ZM%20--%3E%20CAD%0A%20%20CAD%20--%3E%20T%5B%22%E6%B8%A9%E5%BA%A6%20%2F%20%E6%A0%B8%E9%87%87%E6%A0%B7%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[c(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>若某 token 在看见 \\(c\\) 后 logit 升高、看不见时不高，它会被 CAD 进一步抬高；若两边都高（语言先验），差值接近 0，行为接近普通解码。这解释了为什么 CAD 对「证据与先验冲突」最有效，对「证据只是复述常识」几乎无感。它与 DoLa 正交：一个对比层，一个对比条件；可以叠，但归因必须分开做消融。</p><p>两次前向的墙钟接近 2×，除非做成 batch=2 共用权重加载——decode 带宽墙上，同一份权重乘两条序列，算术强度上升，边际成本低于 2。这是后课性能会计会再用的观察：对比解码是「小 batch 变 2」而不是「步数翻倍」。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>没有明确 \\(c\\) 的闲聊不要开 CAD：随便把系统提示当 \\(c\\)，对比的是「有无系统提示」，不是证据忠实。\\(c\\) 极长时，无上下文那次省下的 KV 可观，但有上下文那次仍是长上下文账单。证据互相矛盾时，CAD 会放大冲突里 logit 差更大的那一侧，不一定是对的一侧。评测要钉死 \\(c\\) 的切分（段落、top-k 段落），否则数字不可比。</p><p>出处：Shi et al., NAACL 2024。不要把 PMI 提示或 Dola 的层差写成 CAD。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>CAD 对比有无上下文的逐步分布，放大证据引起的 logit 差。</li><li>需要同步的两条条件，KV 不共享证据段；batch=2 可摊权重加载。</li><li>对象是上下文接地任务；无 \\(c\\) 则无定义。</li><li>与 DoLa、投机叠用时必须声明对比是否进入接受规则。</li><li>\\(\\alpha\\) 过大伤害流畅；过小等于没开。</li><li>后课处理更硬的约束：禁止已出现的 n-gram。</li><li>出处：Shi et al., NAACL 2024。</li></ul>',8))])}const C=i(A,[["render",h]]);export{B as __pageData,C as default};
